package org.sleepwell.app;

import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;

/** Electrical/synthetic arrays only; these do not establish microphone or physical acoustic performance. */
public final class SonarDownsamplerTest {
    private short[] tone(int count,double hz,double amplitude){short[] pcm=new short[count];for(int n=0;n<count;n++)pcm[n]=(short)Math.round(32767*amplitude*Math.sin(2*Math.PI*hz*n/48000));return pcm;}
    private short[] run(short[] pcm,int... chunks){SonarDownsampler filter=new SonarDownsampler();List<Short> values=new ArrayList<>();long previous=-1;for(int at=0,part=0;at<pcm.length;part++){int count=Math.min(chunks[part%chunks.length],pcm.length-at);short[] input=Arrays.copyOfRange(pcm,at,at+count);long first=1000000000L+Math.round(at*(1e9/48000));SonarDownsampler.Output output=filter.accept(input,count,first);if(output!=null){if(previous>=0)assertEquals("Output remains exactly16k through arbitrary chunks",previous,output.fromNanos);previous=output.toNanos;for(short sample:output.pcm)values.add(sample);}at+=count;}short[] result=new short[values.size()];for(int n=0;n<result.length;n++)result[n]=values.get(n);return result;}
    private double rms(short[] pcm){double sum=0;for(short sample:pcm)sum+=(double)sample*sample;return Math.sqrt(sum/pcm.length);}
    @Test public void noStartupOrEofPaddingAndGroupDelayUsesOriginalCaptureClock(){SonarDownsampler filter=new SonarDownsampler();long origin=7000000000L;assertNull(filter.accept(new short[192],192,origin));SonarDownsampler.Output first=filter.accept(new short[1],1,origin+4000000);assertNotNull(first);assertEquals(1,first.pcm.length);assertEquals(origin+2000000,first.fromNanos);assertEquals(origin+2062500,first.toNanos);assertNull(filter.accept(new short[2],2,origin+Math.round(193*(1e9/48000))));SonarDownsampler.Output next=filter.accept(new short[1],1,origin+Math.round(195*(1e9/48000)));assertEquals(first.toNanos,next.fromNanos);assertEquals(1,next.pcm.length);}
    @Test public void completeHistoryAndRatioGiveExactRealSampleCount(){for(int size:new int[]{193,194,195,196,1920,48000}){short[] result=run(tone(size,1000,.3),1920);assertEquals((size-193)/3+1,result.length);}}
    @Test public void arbitraryChunkBoundariesCannotChangeSamplesOrTimestamps(){short[] pcm=tone(50003,1234.5,.5);assertArrayEquals(run(pcm,1920),run(pcm,1,2,17,479,127,3,13,101));}
    @Test public void audiblePassbandIsPreservedWithoutPerBlockNormalization(){for(double hz:new double[]{100,1000,4000,6000}){double input=rms(tone(48000,hz,.2)),output=rms(run(tone(48000,hz,.2),1920));assertEquals("Passband "+hz,input,output,input*.005);}}
    @Test public void aboveNyquistAndSonarCarrierCannotAliasIntoAudibleBand(){double audible=rms(run(tone(48000,1000,.5),1920));for(double hz:new double[]{8000,9000,16000,18500,19000,20000,23000}){double rejected=rms(run(tone(48000,hz,.5),1920));assertTrue("Digital stopband >=70dB versus passband at "+hz+", actual "+rejected,rejected<audible*Math.pow(10,-70d/20));}}
    @Test public void mixedCarrierPreservesActualAudibleSamples(){short[] audible=tone(48000,1000,.2),carrier=tone(48000,19000,.5),mixed=new short[audible.length];for(int n=0;n<mixed.length;n++)mixed[n]=(short)(audible[n]+carrier[n]);short[] expected=run(audible,1920),filtered=run(mixed,1920);double error=0;for(int n=0;n<expected.length;n++){double difference=expected[n]-filtered[n];error+=difference*difference;}assertTrue("Carrier must not masquerade as audible content",Math.sqrt(error/expected.length)<1.5);}
    @Test public void missingRepeatedOrReversedInputIsRejectedBeforeConsumingMoreSamples(){for(long offset:new long[]{-40000000L,-1L+1000000L,40000000L}){SonarDownsampler filter=new SonarDownsampler();filter.accept(new short[1920],1920,1000000000L);assertThrows(IllegalStateException.class,()->filter.accept(new short[1920],1920,1040000000L+offset));SonarDownsampler.Output valid=filter.accept(new short[1920],1920,1040000000L);assertEquals(1038000000L,valid.fromNanos);}}
    @Test public void invalidBlocksAndClockOverflowDoNotProduceSyntheticInput(){SonarDownsampler filter=new SonarDownsampler();assertThrows(IllegalArgumentException.class,()->filter.accept(new short[1921],1921,0));assertThrows(IllegalArgumentException.class,()->filter.accept(new short[5],6,0));assertThrows(IllegalArgumentException.class,()->filter.accept(new short[5],0,0));assertThrows(IllegalArgumentException.class,()->filter.accept(new short[5],5,-1));assertThrows(ArithmeticException.class,()->filter.accept(new short[1920],1920,Long.MAX_VALUE));assertEquals("Rejected overflow cannot anchor or advance the filter",2000000L,filter.accept(new short[193],193,0).fromNanos);}
}
